#include <vector>
#include <utility>
struct Fill { double cost; long long filled; long long shortfall; double avg; };
Fill marketBuy(const std::vector<std::pair<double,long long>>& asks, long long Q){
    double cost = 0; long long rem = Q;
    for (auto& [px, sz] : asks){
        if (rem == 0) break;
        long long take = std::min(rem, sz);
        cost += px * take; rem -= take;
    }
    long long filled = Q - rem;
    return { cost, filled, rem, filled ? cost / filled : 0.0 };
}

def market_buy(asks, Q):
    # asks: list of (price, size) ascending by price
    cost, rem = 0.0, Q
    for px, sz in asks:
        if rem == 0:
            break
        take = min(rem, sz)
        cost += px * take
        rem -= take
    filled = Q - rem
    avg = cost / filled if filled else 0.0
    return {"cost": cost, "filled": filled, "shortfall": rem, "avg": avg}
